package net.battlehub.hub;

import net.battlehub.BattleHub;
import net.battlehub.arch.check.Report;
import net.battlehub.arch.check.Validator;
import net.battlehub.arch.mod.Library;
import net.battlehub.arch.town.Lobby;
import net.battlehub.arena.Blueprint;
import net.battlehub.arena.Build;
import net.battlehub.config.HubConfig;

/**
 * The citadel lobby: generated by the architecture engine ({@code net.battlehub.arch}) as finished block names,
 * checked by its validator, then turned into a blueprint the arena builder places over a few ticks. The plaza,
 * the spawn and the leaderboard balustrade are the same as the classic lobby's.
 */
public final class ArchLobby {
	private ArchLobby() {}

	private static volatile Lobby.Result last;
	private static volatile Report lastReport;

	static Lobby.Settings settings(HubConfig.Lobby cfg) {
		Lobby.Settings s = new Lobby.Settings();
		s.seed = cfg.seed;
		s.detail = cfg.detail;
		s.radius = cfg.islandRadius;
		s.density = cfg.townDensity;
		return s;
	}

	/** Generates the lobby and its blueprint (spawn and the plaza as in the classic lobby). */
	static Blueprint design(HubConfig.Lobby cfg) {
		ArchMaterials.prepare(cfg.discoverModBlocks);
		long t0 = System.nanoTime();
		Lobby.Result r = Lobby.generate(settings(cfg), Library.defaults());
		Report report = Validator.lobby(r, new int[] {0, 1, 9});
		last = r;
		lastReport = report;
		Blueprint bp = new Blueprint();
		r.voxels.forEach((x, y, z, id) -> {
			if (!id.equals("air")) bp.set(x, y, z, Build.s(id));
		});
		bp.spawn(HubLayout.SPAWN_X, HubLayout.SPAWN_Y, HubLayout.SPAWN_Z, HubLayout.SPAWN_YAW);
		bp.spectator(HubLayout.SPAWN_X, HubLayout.SPAWN_Y, HubLayout.SPAWN_Z, HubLayout.SPAWN_YAW, 0);
		bp.radius(cfg.islandRadius + 40);
		bp.voidY(-60);
		for (String line : r.log) BattleHub.LOGGER.info("Architecture: {}", line);
		BattleHub.LOGGER.info("Architecture: lobby generated in {} ms, validation {}", (System.nanoTime() - t0) / 1_000_000, report);
		for (Report.Issue i : report.errors()) BattleHub.LOGGER.warn("Architecture: {}", i);
		return bp;
	}

	/** The last generated lobby (for the self-test), or null. */
	public static Lobby.Result last() {
		return last;
	}

	public static Report lastReport() {
		return lastReport;
	}

	public static java.util.List<String> missingBlocks() {
		return ArchMaterials.missing();
	}
}
